import { OmniComponentHeart } from '@esggo/types';
import React, { useState, useEffect } from 'react';

import {
  Brain,
  Activity,
  Database,
  CheckCircle2,
  ChevronRight,
  Minimize2,
  Maximize2,
} from 'lucide-react';
import { cn } from '../../../lib/utils';
import { OAAgentBus, IOmniEvent } from '../../../lib/omni/OmniAgentBus';

export interface PulseTask {
  id: string;
  type: 'etl_sync' | 'memory_extraction' | 'zkp_seal';
  status: 'pending' | 'active' | 'completed' | 'failed';
  message: string;
}

export function OmniAgentPulse() {
  const [isExpanded, setIsExpanded] = useState(false);
  const [tasks, setTasks] = useState<PulseTask[]>([
    {
      id: 'boot-1',
      type: 'memory_extraction',
      status: 'completed',
      message: 'OmniAgent Pulse 核心已啟動',
    },
  ]);

  // Subscribe to OAAgentBus
  useEffect(() => {
    // 廣通：訂閱全域事件
    const unsubscribe = OAAgentBus.subscribe('*', (event: IOmniEvent) => {
      setTasks((prev) => {
        const newTasks = [...prev];

        // 根據 Event Type 映射 UI icon
        let type: PulseTask['type'] = 'etl_sync';
        if (event.type.includes('SEAL') || event.type.includes('TRUST')) type = 'zkp_seal';
        if (
          event.type.includes('MEMORY') ||
          event.type.includes('EXTRACT') ||
          event.type.includes('NEXUS')
        )
          type = 'memory_extraction';

        // 提取 payload summary，若無則顯示 source
        const payloadStr =
          typeof event.payload === 'object' && event.payload !== null
            ? JSON.stringify(event.payload).substring(0, 30) + '...'
            : String(event.payload || event.source);

        newTasks.unshift({
          id: event.id,
          type,
          status: 'completed',
          message: `[${event.type}] ${payloadStr}`,
        });

        if (newTasks.length > 10) newTasks.pop();
        return newTasks;
      });
    });

    return () => {
      unsubscribe();
    };
  }, []);

  const getIcon = (type: PulseTask['type']) => {
    switch (type) {
      case 'etl_sync':
        return <Database size={14} className="text-blue-400" />;
      case 'zkp_seal':
        return <CheckCircle2 size={14} className="text-emerald-400" />;
      case 'memory_extraction':
        return <Brain size={14} className="text-purple-400" />;
    }
  };

  return (
    <div
      className={cn(
        'fixed z-50 bottom-6 right-6 flex flex-col items-end gap-2',
        'font-sans selection:bg-cyan-500/30'
      )}
    >
      {/* 展開面板 */}
      {isExpanded && (
        <div className="w-72 bg-slate-950/90 border border-cyan-500/30 rounded-2xl p-4 shadow-[0_0_30px_rgba(6,182,212,0.15)] overflow-hidden relative">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent opacity-50" />

          <div className="flex items-center justify-between mb-4 border-b border-white/5 pb-2">
            <div className="flex items-center gap-2 text-cyan-400">
              <Activity size={16} className="animate-pulse" />
              <span className="text-xs font-bold tracking-widest uppercase">
                Agent Pulse Ledger
              </span>
            </div>
            <button
              onClick={() => setIsExpanded(false)}
              className="text-slate-400 hover:text-white transition-colors"
            >
              <Minimize2 size={14} />
            </button>
          </div>

          <div className="space-y-3 max-h-48 overflow-y-auto pr-1 [&::-webkit-scrollbar]:w-1 [&::-webkit-scrollbar-thumb]:bg-cyan-500/30 [&::-webkit-scrollbar-thumb]:rounded-full">
            {tasks.map((task) => (
              <div key={task.id} className="flex items-start gap-3 text-sm">
                <div
                  className={cn(
                    'mt-0.5 shrink-0 rounded-full p-1',
                    task.status === 'active'
                      ? 'bg-cyan-500/20 shadow-[0_0_10px_rgba(6,182,212,0.5)] animate-pulse'
                      : 'bg-white/5'
                  )}
                >
                  {getIcon(task.type)}
                </div>
                <div className="flex-1">
                  <p
                    className={cn(
                      'text-xs font-medium leading-relaxed',
                      task.status === 'active' ? 'text-cyan-100' : 'text-slate-400'
                    )}
                  >
                    {task.message}
                  </p>
                </div>
              </div>
            ))}
            {tasks.length === 0 && (
              <p className="text-xs text-slate-500 text-center py-2">等待萬能心核事件中...</p>
            )}
          </div>
        </div>
      )}

      {/* 懸浮按鈕 (Drag Handle) */}
      <div
        onClick={() => !isExpanded && setIsExpanded(true)}
        className={cn(
          'w-14 h-14 rounded-full flex items-center justify-center cursor-pointer',
          'bg-gradient-to-br from-cyan-500/20 to-blue-600/20 border-md',
          'border border-cyan-400/30 shadow-[0_0_20px_rgba(6,182,212,0.3)]',
          'relative group overflow-hidden'
        )}
      >
        <div className="absolute inset-0 bg-cyan-400/20 opacity-0 group-hover:opacity-100 transition-opacity" />
        <Brain className="text-cyan-400 relative z-10" size={24} />

        {/* Status Indicator Dot */}
        <div className="absolute top-2 right-2 w-2.5 h-2.5 bg-emerald-400 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.8)] animate-pulse" />
      </div>
    </div>
  );
}
